{"version":3,"file":"profile.js","sources":["pages/profile/profile.vue","../../../../../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvcHJvZmlsZS9wcm9maWxlLnZ1ZQ"],"sourcesContent":["<template>\n  <view class=\"profile-bg\">\n  <view class=\"profile-header\">\n      <view class=\"profile-info\">\n        <view class=\"avatar\">👤</view>\n        <view class=\"user-info\">\n          <text class=\"user-name\">{{ userInfo.name || '微信用户' }}</text>\n          <text class=\"user-phone\">{{ userInfo.phone || '*************' }}</text>\n        </view>\n      </view>\n      <template v-if=\"!isLoggedIn\">\n        <button class=\"unbind-btn\" size=\"mini\" @click=\"goLogin\">登录</button>\n      </template>\n      <template v-else>\n        <button class=\"unbind-btn\" size=\"mini\" @click=\"handleLogout\">退出登录</button>\n      </template>\n    </view>\n\n    <view class=\"profile-section card centered centered-down\">\n      <view class=\"profile-row\">\n        <view class=\"profile-item\" @click=\"goToMyCard\">\n          <image class=\"icon icon-lg\" src=\"/static/card.svg\" />\n          <text>我的就诊卡</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToMyPatient\">\n          <image class=\"icon icon-lg\" src=\"/static/patient.svg\" />\n          <text>我的就诊人</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToMyDoctor\">\n          <image class=\"icon icon-lg\" src=\"/static/doctor.svg\" />\n          <text>我的医生</text>\n        </view>\n      </view>\n    </view>\n\n    <view class=\"profile-section card centered centered-down-small\">\n      <view class=\"section-title\">就诊记录</view>\n      <view class=\"profile-row\">\n        <view class=\"profile-item\" @click=\"goToRegisterRecord\">\n          <image class=\"icon\" src=\"/static/register.svg\" />\n          <text>挂号记录</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToOutpatientRecord\">\n          <image class=\"icon\" src=\"/static/outpatient.svg\" />\n          <text>门诊缴费记录</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToHospitalRecord\">\n          <image class=\"icon\" src=\"/static/hospital.svg\" />\n          <text>住院预交记录</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToConsultRecord\">\n          <image class=\"icon\" src=\"/static/consult.svg\" />\n          <text>咨询记录</text>\n        </view>\n      </view>\n      <view class=\"profile-row\">\n        <view class=\"profile-item\" @click=\"goToRevisitRecord\">\n          <image class=\"icon\" src=\"/static/record.svg\" />\n          <text>在线复诊记录</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToCheckRecord\">\n          <image class=\"icon\" src=\"/static/check.svg\" />\n          <text>检查预约记录</text>\n        </view>\n        <view class=\"profile-item\"></view>\n        <view class=\"profile-item\"></view>\n      </view>\n    </view>\n\n    <view class=\"profile-section card\">\n      <view class=\"section-title\">其他</view>\n      <view class=\"profile-row\">\n        <view class=\"profile-item\" @click=\"goToPrivacy\">\n          <image class=\"icon\" src=\"/static/privacy.svg\" />\n          <text>隐私协议</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToHelp\">\n          <image class=\"icon\" src=\"/static/help.svg\" />\n          <text>帮助反馈</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToComplain\">\n          <image class=\"icon\" src=\"/static/complain.svg\" />\n          <text>投诉建议</text>\n        </view>\n        <view class=\"profile-item\" @click=\"goToEvaluate\">\n          <image class=\"icon\" src=\"/static/evaluate.svg\" />\n          <text>就诊评价</text>\n        </view>\n      </view>\n    </view>\n\n    <view class=\"tabbar-placeholder\"></view>\n  </view>\n</template>\n\n<script setup>\nimport { ref, onMounted, computed } from 'vue'\nimport { userApi } from '@/api/user'\nimport { useUserStore } from '@/store/user'\nimport { uniShowToast, uniSwitchTab, uniNavigateTo } from '@/utils/uniHelper'\nimport LoginPrompt from '@/components/LoginPrompt.vue'\nimport { AUTH_REQUIRED_FEATURES, createAuthHandler } from '@/utils/auth'\n\nconst userInfo = ref({})\nconst userStore = useUserStore()\nconst isLoggedIn = computed(() => !!userStore.isLoggedIn)\n\n// 获取用户信息\nconst getUserInfo = () => {\n  // 优先从状态管理获取用户信息\n  if (userStore.userInfo) {\n    userInfo.value = userStore.userInfo\n  } else {\n    // 如果状态管理中没有，则从API获取\n    userApi.getCurrentUser().then(res => {\n      userInfo.value = res.data\n    }).catch(() => {\n      // 如果获取失败，使用默认信息\n      userInfo.value = { name: '微信用户', phone: '***********' }\n    })\n  }\n}\n\n// 使用统一的权限控制创建导航函数\nconst goToMyCard = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.MY_CARD,\n  '/subpkg/profile/personal/mycard',\n  { requireCard: true }\n)\n\nconst goToMyPatient = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.MY_PATIENT,\n  '/subpkg/profile/personal/mypatient'\n)\n\nconst goToMyDoctor = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.MY_DOCTOR,\n  '/subpkg/profile/personal/mydoctor'\n)\n\nconst goToRegisterRecord = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.RECORDS,\n  '/subpkg/profile/records/register-record'\n)\n\nconst goToOutpatientRecord = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.RECORDS,\n  '/subpkg/profile/records/outpatient-record'\n)\n\nconst goToHospitalRecord = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.RECORDS,\n  '/subpkg/profile/records/hospital-record'\n)\n\nconst goToConsultRecord = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.RECORDS,\n  '/subpkg/profile/records/consult-record'\n)\n\nconst goToRevisitRecord = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.RECORDS,\n  '/subpkg/profile/records/revisit-record'\n)\n\nconst goToCheckRecord = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.RECORDS,\n  '/subpkg/profile/records/check-record'\n)\n\nconst goToPrivacy = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.SETTINGS,\n  '/subpkg/profile/settings/privacy'\n)\n\nconst goToHelp = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.SETTINGS,\n  '/subpkg/profile/help/help'\n)\n\nconst goToComplain = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.SETTINGS,\n  '/subpkg/profile/settings/complain'\n)\n\nconst goToEvaluate = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.SETTINGS,\n  '/subpkg/profile/settings/evaluate'\n)\n\nconst goToUnbind = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.PROFILE.SETTINGS,\n  '/subpkg/profile/settings/unbind'\n)\n\nconst goLogin = () => {\n  uni.navigateTo({ url: '/subpkg/auth/login' })\n}\n\n// 退出登录\nconst handleLogout = async () => {\n  try {\n    // 显示确认对话框\n    const res = await new Promise((resolve) => {\n      uni.showModal({\n        title: '确认退出',\n        content: '确定要退出登录吗？',\n        success: (result) => resolve(result.confirm)\n      })\n    })\n\n    if (res) {\n      // 调用后端退出接口（可选）\n      try {\n        await userApi.logout()\n      } catch (e) {\n        // 即使后端退出失败，也要清除本地状态\n        console.log('后端退出失败，但继续清除本地状态')\n      }\n\n      // 清除本地状态\n      userStore.logout()\n\n      // 显示退出成功提示\n      await uniShowToast({ title: '已退出登录' })\n\n      // 跳转到登录页\n      await uniSwitchTab({ url: '/pages/profile/profile' })\n    }\n  } catch (e) {\n    console.log(e)\n    await uniShowToast({ title: '退出失败', icon: 'none' })\n  }\n}\n\nonMounted(() => {\n  getUserInfo()\n})\n</script>\n\n<style scoped>\n.profile-bg {\n  background: #3a9cff;\n  min-height: 100vh;\n  padding-bottom: 72rpx;\n}\n.profile-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 24rpx 24rpx;\n  min-height: 180rpx; /* 个人信息模块在区域内垂直居中 */\n  background: #3a9cff;\n}\n.profile-info {\n  display: flex;\n  align-items: center;\n}\n.avatar {\n  width: 100rpx;\n  height: 100rpx;\n  border-radius: 50%;\n  background: #fff;\n  margin-right: 24rpx;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 48rpx;\n}\n.user-info {\n  display: flex;\n  flex-direction: column;\n  color: #fff;\n}\n.user-name {\n  font-size: 36rpx;\n  font-weight: bold;\n}\n.user-phone {\n  font-size: 26rpx;\n  margin-top: 8rpx;\n}\n.unbind-btn {\n  border: 1px solid #fff;\n  color: #fff;\n  background: transparent;\n  font-size: 26rpx;\n  border-radius: 8rpx;\n  padding: 8rpx 24rpx;\n}\n.card {\n  background: #fff;\n  border-radius: 16rpx;\n  margin: 14rpx 14rpx 0 14rpx; /* 略放松，避免过紧 */\n  padding: 14rpx 0;\n  box-shadow: 0 4rpx 16rpx rgba(58,156,255,0.08);\n}\n.profile-section {\n  display: flex;\n  flex-direction: column;\n  justify-content: flex-start; /* 区块内容靠上且整体居中感 */\n}\n.profile-section.centered {\n  min-height: 180rpx;\n  justify-content: center; /* 该块内竖直居中 */\n}\n.profile-section.centered-down {\n  padding-top: 18rpx; /* 让第一块稍微下移 */\n}\n.profile-section.centered-down-small {\n  min-height: 200rpx;\n  justify-content: center;\n  padding-top: 10rpx; /* 就诊记录整体略向下 */\n}\n.section-title {\n  font-size: 28rpx;\n  font-weight: bold;\n  margin: 0 0 6rpx 32rpx;\n  color: #333;\n}\n.profile-row {\n  display: flex;\n  flex-direction: row;\n  justify-content: flex-start;\n  align-items: center;\n  margin: 0 0 6rpx 0; /* 适当放松行距 */\n}\n.profile-item {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center; /* 新增这一行 */\n  margin: 8rpx 0;\n  padding: 12rpx;\n  border-radius: 12rpx;\n  transition: background-color 0.3s;\n}\n\n.profile-item:active {\n  background-color: rgba(58, 156, 255, 0.1);\n}\n.icon {\n  width: 72rpx;\n  height: 72rpx;\n  margin-bottom: 6rpx;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.icon-lg {\n  width: 88rpx;\n  height: 88rpx;\n  margin-bottom: 12rpx;\n}\n.profile-item text {\n  display: block;\n  text-align: center;\n  line-height: 32rpx;\n  min-height: 64rpx; /* 固定两行高度，保证同一行标题对齐 */\n}\n.tabbar-placeholder {\n  height: 72rpx;\n}\n\n/* 退出登录按钮样式 */\n.logout-section {\n  margin: 20rpx 14rpx 0 14rpx;\n}\n\n.logout-btn {\n  width: 100%;\n  height: 88rpx;\n  background: #ff4757;\n  color: #fff;\n  border: none;\n  border-radius: 12rpx;\n  font-size: 32rpx;\n  font-weight: 500;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: background-color 0.3s;\n}\n\n.logout-btn:active {\n  background: #ff3742;\n}\n</style>\n\n","import MiniProgramPage from 'D:/HuaweiMoveData/Users/zheng/Documents/GitHub/lh7772/校医院挂号系统/pages/profile/profile.vue'\nwx.createPage(MiniProgramPage)"],"names":["ref","useUserStore","computed","userApi","createAuthHandler","AUTH_REQUIRED_FEATURES","uni","uniShowToast","uniSwitchTab","onMounted"],"mappings":";;;;;;;;;;AAuGA,UAAM,WAAWA,cAAG,IAAC,EAAE;AACvB,UAAM,YAAYC,WAAAA,aAAc;AAChC,UAAM,aAAaC,cAAAA,SAAS,MAAM,CAAC,CAAC,UAAU,UAAU;AAGxD,UAAM,cAAc,MAAM;AAExB,UAAI,UAAU,UAAU;AACtB,iBAAS,QAAQ,UAAU;AAAA,MAC/B,OAAS;AAELC,iBAAAA,QAAQ,eAAc,EAAG,KAAK,SAAO;AACnC,mBAAS,QAAQ,IAAI;AAAA,QAC3B,CAAK,EAAE,MAAM,MAAM;AAEb,mBAAS,QAAQ,EAAE,MAAM,QAAQ,OAAO,cAAe;AAAA,QAC7D,CAAK;AAAA,MACF;AAAA,IACH;AAGA,UAAM,aAAaC,WAAiB;AAAA,MAClCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,MACA,EAAE,aAAa,KAAM;AAAA,IACvB;AAEA,UAAM,gBAAgBD,WAAiB;AAAA,MACrCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,eAAeD,WAAiB;AAAA,MACpCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,qBAAqBD,WAAiB;AAAA,MAC1CC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,uBAAuBD,WAAiB;AAAA,MAC5CC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,qBAAqBD,WAAiB;AAAA,MAC1CC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,oBAAoBD,WAAiB;AAAA,MACzCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,oBAAoBD,WAAiB;AAAA,MACzCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,kBAAkBD,WAAiB;AAAA,MACvCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,cAAcD,WAAiB;AAAA,MACnCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,WAAWD,WAAiB;AAAA,MAChCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,IACF;AAEA,UAAM,eAAeD,WAAiB;AAAA,MACpCC,WAAsB,uBAAC,QAAQ;AAAA,MAC/B;AAAA,I